<?php
require __DIR__.'/../app/bootstrap.php';$u=require_admin();$title=t('Platform overview');
$metrics=[['Customers',(int)q("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn()],['Approved sellers',(int)q("SELECT COUNT(*) FROM seller_applications WHERE status='approved'")->fetchColumn()],['Pending applications',(int)q("SELECT COUNT(*) FROM seller_applications WHERE status='pending'")->fetchColumn()],['Active categories',(int)q('SELECT COUNT(*) FROM categories WHERE active=1')->fetchColumn()]];
$pending=all("SELECT s.*,u.full_name FROM seller_applications s JOIN users u ON u.id=s.user_id WHERE s.status='pending' ORDER BY s.submitted_at LIMIT 5");$cats=all('SELECT c.name,COUNT(m.id) n FROM categories c LEFT JOIN menu_items m ON m.category_id=c.id GROUP BY c.id,c.name ORDER BY n DESC');$peak=max(1,...array_column($cats,'n'));require ROOT.'/app/workspace-start.php'; ?>
<div class="dash-header"><div><span class="heading-kicker"><?=e(t('ADMIN CONTROL'))?></span><h1><?=e(t('Platform overview'))?></h1><p class="dash-sub"><?=e(t('The big picture of your food community.'))?></p></div><a class="pill primary" href="<?=e(url('admin/applications.php'))?>"><?=e(t('Review applications →'))?></a></div><div class="metrics"><?php foreach($metrics as [$label,$count]): ?><div class="metric"><div class="metric-icon"><?=ui_icon('chart')?></div><div class="metric-label"><?=e($label)?></div><div class="metric-value"><?=$count?></div></div><?php endforeach ?></div><div class="dash-grid"><section class="panel"><div class="panel-top"><h2><?=e(t('Dishes by category'))?></h2><small><?=e(t('All menu records'))?></small></div><?php foreach($cats as $c): ?><div class="horizontal-metric"><span><?=e(category_label($c['name']))?></span><div class="track"><div style="width:<?=round($c['n']/$peak*100)?>%"></div></div><b><?=$c['n']?></b></div><?php endforeach ?><?php if(!$cats): ?><p class="empty"><?=e(t('Add categories to organize your marketplace.'))?></p><?php endif ?></section><section class="panel lavender"><span class="heading-kicker"><?=e(t('BUILD YOUR MARKETPLACE'))?></span><h2><?=e(t('A place for every flavor.'))?></h2><p><?=e(t('You decide which categories appear to customers and sellers.'))?></p><a class="pill" href="<?=e(url('admin/categories.php'))?>"><?=e(t('Manage categories →'))?></a></section></div><section class="panel list-panel"><div class="panel-top"><h2><?=e(t('Waiting for your review'))?></h2><a href="<?=e(url('admin/applications.php'))?>"><?=e(t('View all →'))?></a></div><?php if(!$pending): ?><p class="empty"><?=e(t('You’re all caught up. No pending applications.'))?></p><?php else: ?><div class="table-wrap"><table><thead><tr><th><?=e(t('Business'))?></th><th><?=e(t('Owner'))?></th><th><?=e(t('Submitted'))?></th><th><?=e(t('Action'))?></th></tr></thead><tbody><?php foreach($pending as $a): ?><tr><td><?=e($a['business_name'])?></td><td><?=e($a['full_name'])?></td><td><?=e(local_time($a['submitted_at']))?></td><td><a class="pill compact" href="<?=e(url('admin/application.php?id='.$a['id']))?>"><?=e(t('Review'))?></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php require ROOT.'/app/workspace-end.php'; ?>
